Explain what the following JavaScript function does and point out any bugs.

function debounce(fn, wait) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn(args), wait);
  };
}

const log = debounce((msg) => console.log(msg), 200);
window.addEventListener('resize', () => log('resized'));

